export async function loadJSON(t){const e=await fetch(t,{headers:{Accept:"application/json"}});if(!e.ok)throw new Error(`Failed to load JSON: ${t} (${e.status})`);return e.json()}export function uniqueSorted(t){const e=t.flatMap(t=>Array.isArray(t)?t:t?[t]:[]);return[...new Set(e.map(t=>String(t).trim()).filter(Boolean))].sort((t,e)=>t.localeCompare(e))}export function filterProjects(t,e={}){const o=(e.term||"").trim().toLowerCase(),n=(e.tag||"").trim().toLowerCase(),r=(e.tech||"").trim().toLowerCase();return t.filter(t=>{const e=(t.tags||[]).map(t=>String(t).toLowerCase()),a=(t.techStack||[]).map(t=>String(t).toLowerCase()),i=[t.title||"",t.description||"",t.id||"",...e,...a].join(" ").toLowerCase();return!(o&&!i.includes(o))&&(!(n&&!e.includes(n))&&!(r&&!a.includes(r)))})}import{loadJSON}from"./dataLoader.js";export function setYearAndSocials(){document.getElementById("year").textContent=(new Date).getFullYear(),loadJSON("data/profile.json").then(t=>{document.getElementById("brand-name").textContent=t.name||"Portfolio";const e=document.getElementById("footer-socials"),o=t.socials||{},n=[["GitHub",o.github],["LinkedIn",o.linkedin],["Twitter",o.twitter],["Email",`mailto:${o.email}`]].filter(([,t])=>!!t);e.innerHTML=n.map(([t,e])=>`<li><a href="${e}" target="_blank" rel="noopener">${t}</a></li>`).join("")}).catch(()=>{})}export function initThemeToggle(){const t=document.getElementById("theme-toggle"),e=e=>{"light"===e?document.documentElement.classList.remove("dark"):document.documentElement.classList.add("dark"),localStorage.setItem("theme",e),t.textContent="light"===e?"☀":"☾"},o=localStorage.getItem("theme");e(o||"dark"),t.addEventListener("click",()=>e(document.documentElement.classList.contains("dark")?"light":"dark"))}